-- POSTGRES / LAKEBASE ONLY. Do not run this in the Databricks SQL editor: it uses Postgres types
-- (text, numeric) and psql's \copy. For Unity Catalog run load_unity_catalog.sql instead.
--
-- Loads the sample water utility star schema into Lakebase (or any Postgres), schema water_star.
-- Generated by generate_star.py. Run from this folder:
--   psql "host=<lakebase-host> dbname=databricks_postgres user=<you> sslmode=require" -f load_lakebase.sql
DROP SCHEMA IF EXISTS water_star CASCADE;
CREATE SCHEMA water_star;

CREATE TABLE water_star.dim_date (
  date_sk integer NOT NULL,
  full_date date NOT NULL,
  year integer NOT NULL,
  quarter integer NOT NULL,
  month integer NOT NULL,
  month_name text NOT NULL,
  day_of_month integer NOT NULL,
  day_of_week integer NOT NULL,
  day_name text NOT NULL,
  is_weekend boolean NOT NULL,
  financial_year text NOT NULL,
  season text NOT NULL,
  CONSTRAINT pk_dim_date PRIMARY KEY (date_sk),
  CONSTRAINT uq_dim_date_business_key UNIQUE (full_date)
);
COMMENT ON TABLE water_star.dim_date IS 'Date dimension: one row per calendar day, smart key yyyymmdd';
COMMENT ON COLUMN water_star.dim_date.date_sk IS 'Smart key yyyymmdd; -1 is unknown';
COMMENT ON COLUMN water_star.dim_date.day_of_week IS '1 = Monday';
COMMENT ON COLUMN water_star.dim_date.financial_year IS 'Australian financial year, July to June, e.g. FY2024';
COMMENT ON COLUMN water_star.dim_date.season IS 'Southern hemisphere season';
\copy water_star.dim_date FROM 'DIM_DATE.csv' WITH (FORMAT csv, HEADER true)

CREATE TABLE water_star.dim_customer (
  customer_sk bigint NOT NULL,
  customer_id text NOT NULL,
  account_no text NOT NULL,
  customer_type text NOT NULL,
  customer_name text NOT NULL,
  suburb text NOT NULL,
  postcode text NOT NULL,
  concession_type text NOT NULL,
  segment text NOT NULL,
  effective_from date NOT NULL,
  effective_to date,
  is_current boolean NOT NULL,
  CONSTRAINT pk_dim_customer PRIMARY KEY (customer_sk),
  CONSTRAINT uq_dim_customer_business_key UNIQUE (customer_id, effective_from)
);
COMMENT ON TABLE water_star.dim_customer IS 'Customer dimension, SCD type 2: a new version when the customer moves or their concession changes';
COMMENT ON COLUMN water_star.dim_customer.customer_sk IS 'Surrogate key; -1 is unknown';
COMMENT ON COLUMN water_star.dim_customer.customer_id IS 'Business key: CRM customer_id';
COMMENT ON COLUMN water_star.dim_customer.effective_to IS 'NULL while current';
\copy water_star.dim_customer FROM 'DIM_CUSTOMER.csv' WITH (FORMAT csv, HEADER true)

CREATE TABLE water_star.dim_meter (
  meter_sk bigint NOT NULL,
  meter_no text NOT NULL,
  meter_size_mm integer NOT NULL,
  meter_type text NOT NULL,
  manufacturer text NOT NULL,
  install_date date,
  CONSTRAINT pk_dim_meter PRIMARY KEY (meter_sk),
  CONSTRAINT uq_dim_meter_business_key UNIQUE (meter_no)
);
COMMENT ON TABLE water_star.dim_meter IS 'Water meter dimension (SCD type 1)';
COMMENT ON COLUMN water_star.dim_meter.meter_sk IS 'Surrogate key; -1 is unknown';
COMMENT ON COLUMN water_star.dim_meter.meter_no IS 'Business key: meter serial number';
\copy water_star.dim_meter FROM 'DIM_METER.csv' WITH (FORMAT csv, HEADER true)

CREATE TABLE water_star.dim_tariff (
  tariff_sk bigint NOT NULL,
  tariff_code text NOT NULL,
  tariff_name text NOT NULL,
  customer_type text NOT NULL,
  tier1_rate_per_kl numeric(8,4) NOT NULL,
  tier1_limit_kl_per_day numeric(6,3) NOT NULL,
  tier2_rate_per_kl numeric(8,4) NOT NULL,
  supply_charge_per_quarter numeric(8,2) NOT NULL,
  CONSTRAINT pk_dim_tariff PRIMARY KEY (tariff_sk),
  CONSTRAINT uq_dim_tariff_business_key UNIQUE (tariff_code)
);
COMMENT ON TABLE water_star.dim_tariff IS 'Water tariff dimension (SCD type 1); rates are fictional';
COMMENT ON COLUMN water_star.dim_tariff.tariff_sk IS 'Surrogate key; -1 is unknown';
COMMENT ON COLUMN water_star.dim_tariff.tariff_code IS 'Business key';
\copy water_star.dim_tariff FROM 'DIM_TARIFF.csv' WITH (FORMAT csv, HEADER true)

CREATE TABLE water_star.dim_site (
  site_sk bigint NOT NULL,
  site_code text NOT NULL,
  site_name text NOT NULL,
  site_type text NOT NULL,
  region text NOT NULL,
  is_drinking_water boolean NOT NULL,
  CONSTRAINT pk_dim_site PRIMARY KEY (site_sk),
  CONSTRAINT uq_dim_site_business_key UNIQUE (site_code)
);
COMMENT ON TABLE water_star.dim_site IS 'Operational site dimension: treatment plants, pump stations, reservoirs';
COMMENT ON COLUMN water_star.dim_site.site_sk IS 'Surrogate key; -1 is unknown';
COMMENT ON COLUMN water_star.dim_site.site_code IS 'Business key: matches LOCATIONS.LOCATION';
\copy water_star.dim_site FROM 'DIM_SITE.csv' WITH (FORMAT csv, HEADER true)

CREATE TABLE water_star.dim_asset (
  asset_sk bigint NOT NULL,
  asset_tag text NOT NULL,
  asset_name text NOT NULL,
  asset_class text NOT NULL,
  system_name text NOT NULL,
  facility_name text NOT NULL,
  manufacturer text,
  criticality integer,
  install_date date,
  CONSTRAINT pk_dim_asset PRIMARY KEY (asset_sk),
  CONSTRAINT uq_dim_asset_business_key UNIQUE (asset_tag)
);
COMMENT ON TABLE water_star.dim_asset IS 'Maintainable equipment dimension (SCD type 1), flattened with its system and facility';
COMMENT ON COLUMN water_star.dim_asset.asset_sk IS 'Surrogate key; -1 is unknown';
COMMENT ON COLUMN water_star.dim_asset.asset_tag IS 'Business key: matches ASSET_GOLDEN.asset_tag';
\copy water_star.dim_asset FROM 'DIM_ASSET.csv' WITH (FORMAT csv, HEADER true)

CREATE TABLE water_star.dim_work_type (
  work_type_sk bigint NOT NULL,
  work_type_code text NOT NULL,
  work_type_name text NOT NULL,
  is_planned boolean NOT NULL,
  CONSTRAINT pk_dim_work_type PRIMARY KEY (work_type_sk),
  CONSTRAINT uq_dim_work_type_business_key UNIQUE (work_type_code)
);
COMMENT ON TABLE water_star.dim_work_type IS 'Maintenance work type dimension';
COMMENT ON COLUMN water_star.dim_work_type.work_type_sk IS 'Surrogate key; -1 is unknown';
COMMENT ON COLUMN water_star.dim_work_type.work_type_code IS 'Business key';
\copy water_star.dim_work_type FROM 'DIM_WORK_TYPE.csv' WITH (FORMAT csv, HEADER true)

CREATE TABLE water_star.dim_wq_parameter (
  parameter_sk bigint NOT NULL,
  parameter_code text NOT NULL,
  parameter_name text NOT NULL,
  unit text NOT NULL,
  guideline_min numeric(10,3),
  guideline_max numeric(10,3),
  CONSTRAINT pk_dim_wq_parameter PRIMARY KEY (parameter_sk),
  CONSTRAINT uq_dim_wq_parameter_business_key UNIQUE (parameter_code)
);
COMMENT ON TABLE water_star.dim_wq_parameter IS 'Drinking water quality parameter dimension; limits are illustrative';
COMMENT ON COLUMN water_star.dim_wq_parameter.parameter_sk IS 'Surrogate key; -1 is unknown';
COMMENT ON COLUMN water_star.dim_wq_parameter.parameter_code IS 'Business key';
\copy water_star.dim_wq_parameter FROM 'DIM_WQ_PARAMETER.csv' WITH (FORMAT csv, HEADER true)

CREATE TABLE water_star.fact_meter_read (
  read_date_sk integer NOT NULL,
  customer_sk bigint NOT NULL,
  meter_sk bigint NOT NULL,
  tariff_sk bigint NOT NULL,
  read_no text NOT NULL,
  read_type text NOT NULL,
  days_in_period integer NOT NULL,
  consumption_kl numeric(10,2) NOT NULL,
  usage_charge numeric(12,2) NOT NULL,
  supply_charge numeric(12,2) NOT NULL,
  CONSTRAINT fk_fact_meter_read_read_date_sk FOREIGN KEY (read_date_sk) REFERENCES water_star.dim_date (date_sk),
  CONSTRAINT fk_fact_meter_read_customer_sk FOREIGN KEY (customer_sk) REFERENCES water_star.dim_customer (customer_sk),
  CONSTRAINT fk_fact_meter_read_meter_sk FOREIGN KEY (meter_sk) REFERENCES water_star.dim_meter (meter_sk),
  CONSTRAINT fk_fact_meter_read_tariff_sk FOREIGN KEY (tariff_sk) REFERENCES water_star.dim_tariff (tariff_sk)
);
COMMENT ON TABLE water_star.fact_meter_read IS 'Billing consumption. Grain: one row per meter read (a customer''s quarterly reading of one meter)';
COMMENT ON COLUMN water_star.fact_meter_read.customer_sk IS 'The customer version in force on the read date';
COMMENT ON COLUMN water_star.fact_meter_read.read_no IS 'Degenerate dimension: billing read number';
COMMENT ON COLUMN water_star.fact_meter_read.read_type IS 'ACTUAL or ESTIMATED';
\copy water_star.fact_meter_read FROM 'FACT_METER_READ.csv' WITH (FORMAT csv, HEADER true)

CREATE TABLE water_star.fact_work_order (
  raised_date_sk integer NOT NULL,
  completed_date_sk integer NOT NULL,
  asset_sk bigint NOT NULL,
  site_sk bigint NOT NULL,
  work_type_sk bigint NOT NULL,
  work_order_no text NOT NULL,
  labour_hours numeric(8,2) NOT NULL,
  labour_cost numeric(12,2) NOT NULL,
  material_cost numeric(12,2) NOT NULL,
  downtime_hours numeric(8,2) NOT NULL,
  CONSTRAINT fk_fact_work_order_raised_date_sk FOREIGN KEY (raised_date_sk) REFERENCES water_star.dim_date (date_sk),
  CONSTRAINT fk_fact_work_order_completed_date_sk FOREIGN KEY (completed_date_sk) REFERENCES water_star.dim_date (date_sk),
  CONSTRAINT fk_fact_work_order_asset_sk FOREIGN KEY (asset_sk) REFERENCES water_star.dim_asset (asset_sk),
  CONSTRAINT fk_fact_work_order_site_sk FOREIGN KEY (site_sk) REFERENCES water_star.dim_site (site_sk),
  CONSTRAINT fk_fact_work_order_work_type_sk FOREIGN KEY (work_type_sk) REFERENCES water_star.dim_work_type (work_type_sk)
);
COMMENT ON TABLE water_star.fact_work_order IS 'Maintenance. Grain: one row per completed work order';
COMMENT ON COLUMN water_star.fact_work_order.work_order_no IS 'Degenerate dimension';
\copy water_star.fact_work_order FROM 'FACT_WORK_ORDER.csv' WITH (FORMAT csv, HEADER true)

CREATE TABLE water_star.fact_water_quality (
  sample_date_sk integer NOT NULL,
  site_sk bigint NOT NULL,
  parameter_sk bigint NOT NULL,
  sample_no text NOT NULL,
  result_value numeric(10,3) NOT NULL,
  exceedance_count integer NOT NULL,
  CONSTRAINT fk_fact_water_quality_sample_date_sk FOREIGN KEY (sample_date_sk) REFERENCES water_star.dim_date (date_sk),
  CONSTRAINT fk_fact_water_quality_site_sk FOREIGN KEY (site_sk) REFERENCES water_star.dim_site (site_sk),
  CONSTRAINT fk_fact_water_quality_parameter_sk FOREIGN KEY (parameter_sk) REFERENCES water_star.dim_wq_parameter (parameter_sk)
);
COMMENT ON TABLE water_star.fact_water_quality IS 'Drinking water quality. Grain: one row per lab result (one parameter of one sample)';
COMMENT ON COLUMN water_star.fact_water_quality.sample_no IS 'Degenerate dimension: lab sample number';
COMMENT ON COLUMN water_star.fact_water_quality.exceedance_count IS '1 when outside the guideline, else 0, so it sums';
\copy water_star.fact_water_quality FROM 'FACT_WATER_QUALITY.csv' WITH (FORMAT csv, HEADER true)

SELECT (SELECT count(*) FROM water_star.dim_date) AS dim_date,
       (SELECT count(*) FROM water_star.dim_customer) AS dim_customer,
       (SELECT count(*) FROM water_star.dim_meter) AS dim_meter,
       (SELECT count(*) FROM water_star.dim_tariff) AS dim_tariff,
       (SELECT count(*) FROM water_star.dim_site) AS dim_site,
       (SELECT count(*) FROM water_star.dim_asset) AS dim_asset,
       (SELECT count(*) FROM water_star.dim_work_type) AS dim_work_type,
       (SELECT count(*) FROM water_star.dim_wq_parameter) AS dim_wq_parameter,
       (SELECT count(*) FROM water_star.fact_meter_read) AS fact_meter_read,
       (SELECT count(*) FROM water_star.fact_work_order) AS fact_work_order,
       (SELECT count(*) FROM water_star.fact_water_quality) AS fact_water_quality;
